function triadElevation(){
 const bridge=(x1,y1,x2,y2)=>`<path d="M${x1} ${y1-9}L${x2} ${y2-9}V${y2+9}L${x1} ${y1+9}Z" fill="#102936" stroke="#81bdcd"/><path d="M${x1} ${y1+4}L${x2} ${y2+4}" stroke="#76edff" stroke-width="3" filter="url(#toraGlow)"/><path d="M${x1} ${y1-4}L${x2} ${y2-4}" stroke="#a7d8df" stroke-width="1"/>`;
 const hub=(x,y,r,scale,part)=>{
  const ribs=Array.from({length:18},(_,i)=>{const a=i*Math.PI/9;return `<path d="M${Math.cos(a)*r*.69} ${Math.sin(a)*r*.32}L${Math.cos(a)*r*.98} ${Math.sin(a)*r*.46}" stroke="#6098aa" stroke-width="1.2"/>`}).join('');
  const teeth=Array.from({length:12},(_,i)=>{const a=i*Math.PI/6;return `<path d="M${Math.cos(a)*r*.94} ${Math.sin(a)*r*.44}l${Math.cos(a)*11} ${Math.sin(a)*6}" stroke="#87cedb" stroke-width="3"/>`}).join('');
  const spires=[[-23,51,9],[-10,101,11],[4,135,10],[17,72,8],[28,43,7]].map(([dx,h,w])=>`<path d="M${dx-w/2} 0V${-h*.6}l${w*.24} -4V${-h}l${w*.32} -11 ${w*.18} 13V${-h*.5}l${w*.26} 4V0Z" fill="#123343" stroke="#8ac8d6" stroke-width=".9"/><path d="M${dx} -7V${-h*.8}" stroke="#96edff" stroke-width="1.3"/>`).join('');
  return `<g transform="translate(${x} ${y}) scale(${scale})">${hardware(part,`<path d="M${-r} 0A${r} ${r*.46} 0 0 0 ${r} 0V13A${r} ${r*.46} 0 0 1 ${-r} 13Z" fill="#102331" stroke="#67a8bb"/><ellipse rx="${r}" ry="${r*.46}" fill="#163646" stroke="#a8dae4" stroke-width="1.6"/><ellipse rx="${r*.77}" ry="${r*.35}" fill="#102b3b" stroke="#649aad"/>${ribs}<ellipse rx="${r*.57}" ry="${r*.26}" fill="#153a4b" stroke="#b1edf4"/><path d="M-23 18L-13 70 0 99 12 62 21 18" fill="#123140" stroke="#649eaf"/><path d="M2 29V85" stroke="#76eaff"/>`)}${hardware(4,`<ellipse rx="${r*.91}" ry="${r*.42}" fill="none" stroke="#78e7f6" stroke-width="2" stroke-dasharray="17 9"/>${teeth}`)}${hardware(part,`<ellipse cy="-8" rx="${r*.45}" ry="${r*.21}" fill="#1b4052" stroke="#88bfcf"/><ellipse cy="-18" rx="${r*.31}" ry="${r*.14}" fill="#173644" stroke="#ace4ed"/><g transform="translate(0 -22)">${spires}</g>`)} </g>`;
 };
 const marks=triadParts.map((p,i)=>`<g class="tora-mark" data-part="${i}" role="button" tabindex="0" aria-label="Inspect ${p.title}" aria-pressed="false"><path d="M${p.x} ${p.y}L${p.lx} ${p.ly-16}H${p.lx+70}" fill="none"/><circle cx="${p.x}" cy="${p.y}" r="6" fill="#0a2531"/><circle cx="${p.x}" cy="${p.y}" r="18" fill="transparent" stroke="none" pointer-events="all"/><text x="${p.lx}" y="${p.ly}">0${i+1} / ${p.label}</text></g>`).join('');
 return `<svg class="tora-plate triad-plate" viewBox="0 0 660 520" xmlns="http://www.w3.org/2000/svg" role="group" aria-label="Circa's Triad schematic, three linked circular hubs and central spires"><defs><pattern id="triadGrid" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0H0V22" fill="none" stroke="#244250" stroke-width=".6"/></pattern><radialGradient id="triadBackdrop"><stop stop-color="#153443"/><stop offset="1" stop-color="#08131d"/></radialGradient><filter id="toraAmber"><feColorMatrix type="matrix" values="0 1.35 0 0 .06 0 .82 0 0 .01 0 .30 0 0 0 0 0 0 1 0"/></filter><filter id="toraGlow"><feGaussianBlur stdDeviation="1.6"/><feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><rect width="660" height="520" fill="url(#triadBackdrop)"/><rect width="660" height="520" fill="url(#triadGrid)"/><path d="M28 466H632M38 460V472M622 460V472" fill="none" stroke="#6c9fac"/><text x="330" y="485" text-anchor="middle" fill="#a7d3df" font-size="10" font-family="monospace">182 km · PUBLISHED OVERALL LENGTH</text><g class="tora-build">${hardware(3,bridge(186,308,270,281)+bridge(404,246,506,211))}${hub(538,202,83,.82,2)}${hub(330,268,112,1,1)}${hub(133,331,91,.93,0)}</g><g class="tora-scan"><path d="M32 484H628" stroke="#a1f6ff" opacity=".7"/></g><g class="tora-marks">${marks}</g><g fill="#83aab9" font-size="9" font-family="monospace" letter-spacing="1.2"><text x="22" y="22">CIRCA'S TRIAD / STRUCTURAL STUDY</text><text x="638" y="22" text-anchor="end">COLUMA</text><text x="22" y="508">EXTERIOR INTERPRETATION</text><text x="638" y="508" text-anchor="end">SCHEMATIC / NTS</text></g></svg>`;
}
